pub(crate) fn prepare(program:&mut crate::syntax::Program)->Result<(),crate::Diagnostic>{
 use crate::syntax::ExprKind;
 let mut used=program.records.iter().any(|r|r.native_type.is_some_and(|id|crate::native_types::declaration(id).module=="std:sql"));
 for function in &mut program.functions{crate::source_walk::function_body(function,&mut |_|Ok(()),&mut |expression|{
 if let ExprKind::Call(callee,args)=&mut expression.kind && matches!(&callee.kind,ExprKind::Name(name) if name=="@native:std:sql#connect") {let args=std::mem::take(args);crate::stdlib::futures::lazy_module(expression,"std:sql","__connect",args);used=true;}Ok(())})?;}
 if used{for binding in OPERATIONS{crate::native_binding_types::prepare(&mut program.records,binding,crate::Span::default())?;}}Ok(())
}
pub(crate) fn asynchronous(name:&str)->bool{matches!(name,"connect"|"__connect"|"__begin"|"__migrate"|"__close"|"__execute"|"__query"|"__cursor"|"__cursorNext"|"__txexecute"|"__txquery"|"__commit"|"__rollback")}
pub(crate) fn method(id:Option<NativeTypeId>,member:&str)->Option<&'static str>{use NativeTypeId::*;Some(match(id,member){
(Some(SqlCursor),"next")=>"__cursorNext",(Some(SqlCursor),"close")=>"__cursorClose",(Some(SqlPool),"cursor")=>"__cursor",
(Some(SqlPool),"migrate")=>"__migrate",(Some(SqlPool),"begin")=>"__begin",(Some(SqlPool),"close")=>"__close",(Some(SqlPool),"execute")=>"__execute",(Some(SqlPool),"query")=>"__query",
(Some(SqlTransaction),"execute")=>"__txexecute",(Some(SqlTransaction),"query")=>"__txquery",(Some(SqlTransaction),"commit")=>"__commit",(Some(SqlTransaction),"rollback")=>"__rollback",
(Some(SqlRow),"int")=>"__int",(Some(SqlRow),"number")=>"__number",(Some(SqlRow),"boolean")=>"__boolean",(Some(SqlRow),"text")=>"__text",(Some(SqlRow),"blob")=>"__blob",(Some(SqlRow),"isNull")=>"__isNull",_=>return None})}
